def remove_occ(s: str, ch: str) -> str:
    # Validate inputs
    if not isinstance(s, str) or not isinstance(ch, str):
        raise ValueError("Both inputs must be strings.")
    if len(ch) != 1:
        raise ValueError("Second parameter must be a single character.")

    # Create a list of characters excluding the first and last occurrence of 'ch'
    chars = list(s)
    first_occ = chars.index(ch) if ch in chars else -1
    last_occ = chars.rindex(ch) if ch in chars else -1

    if first_occ != -1:
        del chars[first_occ]
    if last_occ != -1 and last_occ > first_occ:
        del chars[last_occ - 1]

    return ''.join(chars)

