def counting_sort(arr):
    if not isinstance(arr, list):
        raise TypeError("Input must be a list")

    if not arr:
        return []

    # Ensure all elements are non-negative integers
    if not all(isinstance(x, int) and x >= 0 for x in arr):
        raise ValueError("All elements must be non-negative integers")

    # Find the maximum value in the array to determine the range of the count array
    max_val = max(arr)

    # Initialize the count array with zeros, with a length of max_val + 1
    count = [0] * (max_val + 1)

    # Count each element in the input array
    for num in arr:
        count[num] += 1

    # Reconstruct the sorted array
    sorted_arr = []
    for num, freq in enumerate(count):
        sorted_arr.extend([num] * freq)

    return sorted_arr

